on conflict (id) do update set
  start_date = excluded.start_date,
  end_date   = excluded.end_date,
  pcs_slug   = coalesce(public.tours.pcs_slug, excluded.pcs_slug),
  info       = public.tours.info || excluded.info;

-- Tour de France 2027: Etappen
insert into public.stages (tour_id, number, starts_at, kind, departure, arrival, distance_km, elevation_m, climbs, info) values
  ('tour-2027', 1, (('2027-07-02'::date + time '12:00') at time zone 'Europe/Berlin'), 'flat', 'Edinburgh', 'Carlisle', 185, 2000, '[{"name":"Côte de Melrose","cat":"?","km":65,"len":2.2,"grad":6.7,"alt":247}]'::jsonb, '{"route":"Von Edinburgh durch die Scottish Borders über Innerleithen, Galashiels und Hawick nach England. Einzige Bergwertung ist die Côte de Melrose (2,2 km, 6,7 %) bei km 65, danach wellig und zum Schluss flach nach Carlisle.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 2, (('2027-07-03'::date + time '12:00') at time zone 'Europe/Berlin'), 'hilly', 'Keswick', 'Liverpool', 223, 3000, '[{"name":"Côte de Jubilee Tower","cat":"?","km":88,"len":3.8,"grad":6.1,"alt":285},{"name":"Côte de Trough of Bowland","cat":"?","km":98.5,"len":1.9,"grad":5.2,"alt":293},{"name":"Côte de Waddington Fell","cat":"?","km":112,"len":3.4,"grad":6.4,"alt":347},{"name":"Côte de Belmont","cat":"?","km":152.5,"len":2,"grad":4,"alt":326},{"name":"Côte de Parbold","cat":"?","km":183,"len":1.8,"grad":5.6,"alt":122}]'::jsonb, '{"route":"Aus dem Lake District nach Lancashire. In der zweiten Hälfte fünf kurze Bergwertungen – Jubilee Tower, Trough of Bowland, Waddington Fell, Belmont und Parbold bei km 183 –, dann flach nach Liverpool.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 3, (('2027-07-04'::date + time '12:00') at time zone 'Europe/Berlin'), 'hilly', 'Welshpool', 'Cardiff', 223, 3000, '[{"name":"Côte d''Epynt","cat":"?","km":85.5,"len":3.7,"grad":7.9,"alt":450},{"name":"Côte de Bannau Brycheiniog","cat":"?","km":121.5,"len":6.6,"grad":3.5,"alt":441},{"name":"Côte de Rhigos","cat":"?","km":145.5,"len":4.6,"grad":5.8,"alt":486},{"name":"Côte de Penrhys","cat":"?","km":160.5,"len":1.3,"grad":10.1,"alt":284},{"name":"Côte de Maerdy","cat":"?","km":169,"len":1.5,"grad":8.7,"alt":408},{"name":"Côte de Hengoed","cat":"?","km":197.5,"len":0.7,"grad":11,"alt":194},{"name":"Côte de Caerphilly","cat":"?","km":210.5,"len":2,"grad":8.2,"max":11.8,"alt":249}]'::jsonb, '{"route":"Komplett durch Wales mit acht Bergwertungen, die meisten im letzten Drittel durch die Rhondda-Täler: Rhigos, Penrhys (1,3 km, 10,1 %), Maerdy, Hengoed (0,7 km, 11 %) und 12,5 km vor dem Ziel die Côte de Caerphilly (2 km, 8,2 %, bis 11,8 %).","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 4, (('2027-07-06'::date + time '12:00') at time zone 'Europe/Berlin'), 'hilly', 'Cherbourg-en-Cotentin', 'Cherbourg-en-Cotentin', 171, 2200, '[]'::jsonb, '{"route":"Erste Etappe in Frankreich, ein Rundkurs über die Halbinsel Cotentin: erst durch La Hague im Westen, dann an der Ostküste über Saint-Vaast-la-Hougue und Barfleur zurück. Keine Bergwertung, aber ständig wellig.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 5, (('2027-07-07'::date + time '12:00') at time zone 'Europe/Berlin'), 'hilly', 'Pontorson', 'Plumelec', 178, 1900, '[{"name":"Côte de Cadoudal","cat":"?","km":164,"len":1.7,"grad":6.2,"max":7.2,"alt":153},{"name":"Plumelec – Côte de Cadoudal","cat":"?","km":178,"len":1.7,"grad":6.2,"max":7.2,"alt":153}]'::jsonb, '{"route":"Start an der Bucht des Mont-Saint-Michel, quer durch die Bretagne. Im Finale zweimal die Côte de Cadoudal (1,7 km, 6,2 %): bei km 164 und als Zielanstieg in Plumelec.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 6, (('2027-07-08'::date + time '12:00') at time zone 'Europe/Berlin'), 'hilly', 'Vannes', 'Angers', 193, 1500, '[]'::jsonb, '{"route":"Von der Bretagne an die Loire, ohne Bergwertung und mit nur 1.500 Höhenmetern – eine Chance für die Sprinter.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 7, (('2027-07-09'::date + time '12:00') at time zone 'Europe/Berlin'), 'itt', 'Blois', 'Chambord', 38, 200, '[]'::jsonb, '{"route":"Flaches Einzelzeitfahren durch das Loiretal über Cellettes, Cour-Cheverny und Mont-près-Chambord zum Schloss Chambord.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 8, (('2027-07-10'::date + time '12:00') at time zone 'Europe/Berlin'), 'hilly', 'Bourges', 'Le Creusot', 224.5, 3100, '[{"name":"Côte de la Croix de la Libération","cat":"?","km":189,"len":4.6,"grad":5.3,"alt":577},{"name":"Signal d''Uchon","cat":"?","km":206.5,"len":5.7,"grad":5.7,"max":18,"alt":635}]'::jsonb, '{"route":"Längste Etappe der Tour. Flach bis Nevers, dann durch den Morvan (Col de la Gravelle, 774 m). Im Finale die Côte de la Croix de la Libération (4,6 km, 5,3 %) und 18 km vor dem Ziel der Signal d’Uchon (5,7 km, 5,7 %, Rampe mit 18 %).","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 9, (('2027-07-11'::date + time '12:00') at time zone 'Europe/Berlin'), 'mountain', 'Villars-les-Dombes', 'Grand Colombier', 162, 3750, '[{"name":"Col du Berthiand","cat":"?","km":57.5,"len":6.3,"grad":7.5,"alt":780},{"name":"Côte des Neyrolles","cat":"?","km":77,"len":3.6,"grad":7.7,"alt":825},{"name":"Col de Richemond","cat":"?","km":115,"len":7.7,"grad":6,"alt":1036},{"name":"Grand Colombier","cat":"?","km":162,"len":17.4,"grad":7.1,"max":12,"alt":1501}]'::jsonb, '{"route":"Erste Bergankunft. Nach Col du Berthiand, Côte des Neyrolles und Col de Richemond geht es von Culoz hinauf zum Grand Colombier: 17,4 km mit 7,1 %, Abschnitte mit 12 %.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 10, (('2027-07-13'::date + time '12:00') at time zone 'Europe/Berlin'), 'mountain', 'Annecy', 'Sallanches', 171, 3750, '[{"name":"Col du Plan du Salève","cat":"?","km":26,"len":9.6,"grad":5.4,"alt":1300},{"name":"Montée de Brison","cat":"?","km":74,"len":5,"grad":10.2,"alt":991},{"name":"Côte de Domancy","cat":"?","km":111.5,"len":2.5,"grad":9.4,"max":11,"alt":810},{"name":"Montée du Bettex","cat":"?","km":126.5,"len":5.5,"grad":8,"alt":1353},{"name":"Côte du Plateau d''Assy","cat":"?","km":147.5,"len":5.1,"grad":7.5,"alt":990},{"name":"Côte de Domancy","cat":"?","km":162,"len":2.5,"grad":9.4,"max":11,"alt":810}]'::jsonb, '{"route":"Sechs Bergwertungen in Hochsavoyen: Col du Plan du Salève und Montée de Brison, dann ab Sallanches eine Schleife mit Côte de Domancy, Montée du Bettex und Côte du Plateau d’Assy. Die zweite Auffahrt zur Côte de Domancy (2,5 km, 9,4 %) endet 9 km vor dem Ziel.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 11, (('2027-07-14'::date + time '12:00') at time zone 'Europe/Berlin'), 'mountain', 'Cluses', 'Les Saisies', 150, 4750, '[{"name":"Col de la Colombière","cat":"?","km":16,"len":15.9,"grad":7,"alt":1618},{"name":"Col de la Croix Fry","cat":"?","km":40,"len":7.2,"grad":5.5,"alt":1477},{"name":"Col de la Forclaz de Queige","cat":"?","km":85,"len":5.1,"grad":8.2,"alt":853},{"name":"Col du Pré","cat":"?","km":113,"len":12.6,"grad":7.8,"max":11.3,"alt":1748},{"name":"Montée de Bisanne","cat":"?","km":146,"len":12.4,"grad":8.3,"max":10,"alt":1723}]'::jsonb, '{"route":"Kurze, schwere Bergetappe am Nationalfeiertag mit fünf Anstiegen: Col de la Colombière (15,9 km, 7 %), Col de la Croix Fry, Col de la Forclaz de Queige, Col du Pré (12,6 km, 7,8 %) und zum Schluss die Montée de Bisanne (12,4 km, 8,3 %) – das Ziel in Les Saisies liegt 4 km nach dem Gipfel.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 12, (('2027-07-15'::date + time '12:00') at time zone 'Europe/Berlin'), 'flat', 'Chambéry', 'Valence', 162, 1600, '[]'::jsonb, '{"route":"Aus den Alpen über Voiron und Roybon hinunter ins Rhonetal nach Valence, ohne Bergwertung – eine Etappe für die Sprinter.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 13, (('2027-07-16'::date + time '12:00') at time zone 'Europe/Berlin'), 'flat', 'Aubenas', 'Montpellier', 164, 1500, '[]'::jsonb, '{"route":"Aus der Ardèche über Alès und Anduze ans Mittelmeer nach Montpellier, ohne Bergwertung.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 14, (('2027-07-17'::date + time '12:00') at time zone 'Europe/Berlin'), 'mountain', 'Montpellier', 'Mende', 199, 4300, '[{"name":"Col du Vent","cat":"?","km":40.5,"len":8.4,"grad":5.8,"alt":703},{"name":"Col de la Lusette","cat":"?","km":108.5,"len":11.6,"grad":7.3,"alt":1351},{"name":"Côte de l''Estrade","cat":"?","km":175,"len":5.7,"grad":8.3,"alt":1002},{"name":"Côte de la Croix Neuve (Montée Jalabert)","cat":"?","km":197.5,"len":3,"grad":10.1,"max":10.9,"alt":1055}]'::jsonb, '{"route":"Durch den Cirque de Navacelles in die Cevennen: Col du Vent, Col de la Lusette (11,6 km, 7,3 %) und Mont Aigoual (1.552 m). Im Finale die Côte de l’Estrade und die Montée Jalabert (Côte de la Croix Neuve, 3 km, 10,1 %), deren Gipfel 1,5 km vor dem Ziel liegt.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 15, (('2027-07-18'::date + time '12:00') at time zone 'Europe/Berlin'), 'hilly', 'Rodez', 'Albi', 168, 2500, '[]'::jsonb, '{"route":"Ständig auf und ab durch Aveyron und Tarn, ohne Bergwertung, zum Schluss hinunter nach Albi.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 16, (('2027-07-20'::date + time '12:00') at time zone 'Europe/Berlin'), 'itt', 'Toulouse', 'Toulouse', 33, 200, '[{"name":"Côte de Pech David","cat":"?","km":24,"len":0.8,"grad":12.4,"alt":249}]'::jsonb, '{"route":"Flaches Einzelzeitfahren südlich von Toulouse entlang der Garonne – mit einer Ausnahme: der Côte de Pech David (0,8 km, 12,4 %) 9 km vor dem Ziel.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 17, (('2027-07-21'::date + time '12:00') at time zone 'Europe/Berlin'), 'flat', 'Muret', 'Pau', 186, 2000, '[]'::jsonb, '{"route":"Über die Hügel von Comminges und Bigorre nach Pau, ohne Bergwertung.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 18, (('2027-07-22'::date + time '12:00') at time zone 'Europe/Berlin'), 'mountain', 'Pau', 'Saint-Lary-Soulan (Col du Portet)', 174, 5400, '[{"name":"Col du Soulor","cat":"?","km":50,"len":11.8,"grad":7.3,"alt":1474},{"name":"Col du Tourmalet (Souvenir Jacques Goddet)","cat":"?","km":106.5,"len":19,"grad":7.4,"max":10.9,"alt":2115},{"name":"Hourquette d''Ancizan","cat":"?","km":140.5,"len":8.2,"grad":5.1,"alt":1564},{"name":"Col du Portet (Souvenir Henri Desgrange)","cat":"?","km":174,"len":16,"grad":8.7,"alt":2215}]'::jsonb, '{"route":"Königsetappe mit 5.400 Höhenmetern: Col du Soulor, Col du Tourmalet (19 km, 7,4 %, Souvenir Jacques Goddet), Hourquette d’Ancizan und als Ziel der Col du Portet (16 km, 8,7 %) auf 2.215 m – der höchste Punkt der Tour (Souvenir Henri Desgrange).","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 19, (('2027-07-23'::date + time '12:00') at time zone 'Europe/Berlin'), 'mountain', 'Hasparren', 'Laruns', 160, 4300, '[{"name":"Col de Burdincurutcheta","cat":"?","km":44.5,"len":8.7,"grad":9.3,"max":15,"alt":1135},{"name":"Col de Bagargui","cat":"?","km":52.5,"len":4.8,"grad":6.4,"max":9.7,"alt":1330},{"name":"Col de Soudet","cat":"?","km":95.5,"len":15.1,"grad":7.2,"alt":1540},{"name":"Col de Marie Blanque","cat":"?","km":141.5,"len":7.7,"grad":8.6,"alt":1035}]'::jsonb, '{"route":"Letzte Bergetappe durch das Baskenland und das Béarn: Col de Burdincurutcheta (8,7 km, 9,3 %, Rampen mit 15 %), Col de Bagargui, Col de Soudet (15,1 km, 7,2 %) und 18,5 km vor dem Ziel der Col de Marie Blanque (7,7 km, 8,6 %).","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 20, (('2027-07-24'::date + time '12:00') at time zone 'Europe/Berlin'), 'flat', 'Maubourguet', 'Libourne', 198, 1700, '[]'::jsonb, '{"route":"Flach durch Gers und Lot-et-Garonne in die Gironde nach Libourne.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb),
  ('tour-2027', 21, (('2027-07-25'::date + time '12:00') at time zone 'Europe/Berlin'), 'flat', 'Saint-Quentin-en-Yvelines', 'Paris (Champs-Élysées)', 116, 800, '[]'::jsonb, '{"route":"Schlussetappe von Saint-Quentin-en-Yvelines nach Paris, Ziel auf den Champs-Élysées.","source":"offizielle Streckenpräsentation vom 22.10.2026 (Profile auf letour.fr)"}'::jsonb)
on conflict (tour_id, number) do update set
  starts_at   = case when (public.stages.starts_at at time zone 'Europe/Berlin')::date = (excluded.starts_at at time zone 'Europe/Berlin')::date
                     then public.stages.starts_at else excluded.starts_at end,
  kind        = excluded.kind,
  departure   = excluded.departure,
  arrival     = excluded.arrival,
  distance_km = excluded.distance_km,
  elevation_m = excluded.elevation_m,
  climbs      = excluded.climbs,
  info        = public.stages.info || excluded.info
  where not public.stages.results_published;

