) as x(number, points, waypoints) join public.stages s on s.tour_id = 'tour-2027' and s.number = x.number
on conflict (stage_id) do update set points = excluded.points, waypoints = excluded.waypoints, updated_at = now()
  where public.stage_profiles.source = excluded.source;

commit;

-- Kontrolle
select t.id, t.start_date, t.end_date, count(s.id) as etappen, count(p.stage_id) as profile
  from public.tours t left join public.stages s on s.tour_id = t.id left join public.stage_profiles p on p.stage_id = s.id
 where t.id in ('giro-2027', 'tour-2027', 'vuelta-2027')
 group by t.id, t.start_date, t.end_date order by t.start_date;
